"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse safety-monitor log lines into transcripts (SPEC.md section 4)."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day_text, flag_text = fields
        try:
            day = int(day_text)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if flag_text == "1":
            flagged = True
        elif flag_text == "0":
            flagged = False
        elif flag_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: flagged must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out


def dedupe_transcripts(events):
    """Keep the last record for each id, sorted by day then id (SPEC.md section 5)."""
    latest_by_id = {}
    for event in events:
        latest_by_id[event["id"]] = event
    return sorted(latest_by_id.values(), key=lambda event: (event["day"], event["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Count flagged transcripts on each inclusive day in the range (SPEC.md section 6)."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event.get("flagged") is True:
            counts[day - start_day] += 1
    return counts

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate(
        [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    ) == 1 / 3
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "many": [{"flagged": True}] + [{"flagged": False}] * 9,
        "one": [{"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.2
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window_uses_exactly_last_days():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 5) == 6


def test_parse_transcript_log_values_and_skipped_lines():
    assert parse_transcript_log(
        ["  # heading", "", "  ", " x1 , 3 , 1 ", "x2,4,0", "x3,5,"]
    ) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,nope,1"])
def test_parse_transcript_log_error_has_original_line_number(line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# comment", line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    events = [
        {"id": "same", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": None},
        {"id": "a", "day": 2, "flagged": True},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "same", "day": 3, "flagged": None},
    ]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": True},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 4) == [1, 0, 1]
    assert daily_flag_counts(events, 5, 4) == []


def test_monitor_summary_rounds_and_counts_only_nonempty_groups():
    groups = {
        "flags": [{"day": 1, "flagged": True}, {"day": 3, "flagged": True}],
        "miss": [{"day": 2, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 1) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": True}],
        "a": [{"flagged": True}, {"flagged": False}],
    }
    assert top_flagged_groups(groups, 5) == ["b", "z", "a"]
    assert top_flagged_groups(groups, 1) == ["b"]


def test_flag_rate_by_group_sorted_and_empty_is_none():
    rates = flag_rate_by_group({"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]})
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_counts_positive_entries_only():
    assert longest_flag_streak([1, 2, 0, 1, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
